"""Splice the section labs into one 62-bar file (lab/99_assembled.ly) by time, and check the joins.
This is an integrity check of the design, not the composer's score."""
import re
from fractions import Fraction as F
from p3 import mel, N, to_ly

VOICES = ['soprano', 'alto', 'tenor', 'bass']


def voices_of(path):
    src = open(path).read()
    out = {}
    for v in VOICES:
        m = re.search(r"(?ms)^" + v + r" = \\absolute \{(.*?)^\}", src)
        out[v] = mel(m.group(1))
    return out


def cut(notes, t0, t1, shift):
    """notes overlapping [t0, t1), clipped, shifted by `shift` quarters"""
    res = []
    for n in notes:
        s, e = n.t, n.t + n.d
        if e <= t0 or s >= t1:
            continue
        s2, e2 = max(s, t0), min(e, t1)
        res.append(n.copy(t=s2 + shift, d=e2 - s2))
    return res


plan = [  # (lab file, first lab bar, last lab bar)
    ('01_exposition.ly', 1, 17),
    ('14_episode1.ly', 2, 3),
    ('13_second_subject.ly', 1, 8),
    ('12_stretto_to_crisis.ly', 1, 6),
    ('10_crisis_mirror.ly', 1, 9),
    ('08_climax.ly', 1, 9),
    ('09_apotheosis.ly', 1, 11),
]
piece = {v: [] for v in VOICES}
bar = 1
for f, a, b in plan:
    vs = voices_of(f)
    for v in VOICES:
        piece[v] += cut(vs[v], F(4 * (a - 1)), F(4 * b), F(4 * (bar - a)))
    bar += b - a + 1
assert bar == 63, bar
# bar 28: keep the first half of lab 13's bar 9 (S f''2, A des''2, B bes,2) over lab 12's bar 1
t28 = F(4 * 27)
fix = {'soprano': "f''2", 'alto': "des''2", 'bass': "bes,2"}
for v, s in fix.items():
    piece[v] = [n for n in piece[v] if not (t28 <= n.t < t28 + 2)] + mel(s + " ", t0=t28)
# bar 43: tenor f' on the first beat (lab 10's last note) before CS2 enters on beat 2
t43 = F(4 * 42)
piece['tenor'] = [n for n in piece['tenor'] if not (t43 <= n.t < t43 + 1)] + mel("f'4", t0=t43)
with open('99_assembled.ly', 'w') as fh:
    fh.write("% Proposal 3, lab 99: all section labs spliced by time into one 62-bar file (integrity check).\n"
             "% GENERATED by assemble_check.py from labs 01, 14, 13, 12, 10, 08, 09.\n")
    for v in VOICES:
        ns = sorted([n for n in piece[v] if n.step is not None], key=lambda n: n.t)
        # merge a note with an identical following note that was split at a lab boundary only if tied in the source: keep separate (re-attack)
        fh.write(f"{v} = \\absolute {{\n  " + to_ly(ns, F(4 * 62)) + "\n}\n")
print('wrote 99_assembled.ly')
